#!/usr/bin/env python3
"""Validate and extract the ZIP generated by Forge without escaping its root."""
import argparse
import os
from pathlib import Path, PurePosixPath
import posixpath
import stat
import subprocess
import zipfile


def extract_linux_zip(archive, destination, root="NexusIDE-linux-x64"):
    archive = Path(archive).resolve(strict=True)
    destination = Path(destination)
    if destination.exists() or destination.is_symlink():
        raise ValueError("ZIP extraction directory must not already exist")
    expected_root = PurePosixPath(root)
    if len(expected_root.parts) != 1 or root in ("", ".", ".."):
        raise ValueError("invalid ZIP application root")
    names = set()
    links = set()
    with zipfile.ZipFile(archive) as bundle:
        for entry in bundle.infolist():
            name = entry.filename.rstrip("/")
            parts = name.split("/")
            if (not name or "\\" in name or any(ord(char) < 32 for char in name)
                    or name.startswith("/") or any(part in ("", ".", "..") for part in parts)
                    or parts[0] != root or name in names):
                raise ValueError("ZIP contains an invalid, duplicate or escaping path")
            names.add(name)
            mode = entry.external_attr >> 16
            kind = stat.S_IFMT(mode)
            if kind not in (0, stat.S_IFREG, stat.S_IFDIR, stat.S_IFLNK):
                raise ValueError("ZIP contains a special filesystem entry")
            if kind == stat.S_IFLNK:
                if entry.file_size > 4096:
                    raise ValueError("ZIP symlink target is too large")
                target = bundle.read(entry).decode("utf-8")
                resolved = posixpath.normpath(posixpath.join(posixpath.dirname(name), target))
                if (not target or "\\" in target or "\0" in target or target.startswith("/")
                        or not (resolved == root or resolved.startswith(root + "/"))):
                    raise ValueError("ZIP symlink escapes its application root")
                links.add(name)
        # unzip must never write through a link created by an earlier entry.
        for name in names:
            ancestors = (str(parent) for parent in PurePosixPath(name).parents)
            if any(parent in links for parent in ancestors):
                raise ValueError("ZIP entry has a symlink parent")
        binary_name = f"{root}/nexus-ide"
        if binary_name not in names or binary_name in links:
            raise ValueError("ZIP lacks its regular Linux executable")
    destination.mkdir(parents=True)
    subprocess.run(["unzip", "-q", str(archive), "-d", str(destination)], check=True)
    extracted_root = (destination / root).resolve(strict=True)
    for folder, directories, files in os.walk(extracted_root, followlinks=False):
        for name in directories + files:
            resolved = (Path(folder) / name).resolve(strict=False)
            if not resolved.is_relative_to(extracted_root):
                raise ValueError("extracted ZIP link escapes its application root")
    binary = extracted_root / "nexus-ide"
    if not binary.is_file() or binary.is_symlink() or not os.access(binary, os.X_OK):
        raise ValueError("extracted ZIP executable is not runnable")
    with binary.open("rb") as executable:
        header = executable.read(20)
    if (len(header) != 20 or header[:6] != b"\x7fELF\x02\x01"
            or int.from_bytes(header[18:20], "little") != 62):
        raise ValueError("extracted ZIP executable must be Linux ELF x86-64")
    return binary


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--archive", required=True)
    parser.add_argument("--out", required=True)
    args = parser.parse_args()
    print(extract_linux_zip(args.archive, args.out))
